using AdForLinux.DirectoryServices;
using AdForLinux.DirectoryServices.Security.Core;
using Xunit;
using static AdForLinux.FunctionalTests.SecurityDescriptorFixtures;
using CoreAce = AdForLinux.DirectoryServices.Security.Core.Ace;

namespace AdForLinux.FunctionalTests;

public partial class AclMutationReplayTests
{
    // Raw inputs and Microsoft after-add outputs below are literal I2 transcript bytes.
    // D13 approves the six understood inactive families; Microsoft's broader drops are
    // not permission to lose unknown data. SACL neighbor sorting remains unapproved.
    [Theory]
    [MemberData(nameof(RecordedI2Mutations))]
    public void I2_mutation_matches_approved_output_or_refuses_atomically(string caseName,
        string inputHex, string microsoftOutputHex, bool sacl, bool mustRefuse)
    {
        Assert.False(string.IsNullOrEmpty(caseName));
        var input = Convert.FromHexString(inputHex);
        var engine = new AclMutationEngine(SecurityDescriptor.Parse(input, All));
        var section = sacl ? SecurityMasks.Sacl : SecurityMasks.Dacl;
        var rule = CoreAce.Read(Ace((byte)(sacl ? 2 : 0), (byte)(sacl ? 0x40 : 0), 0x100, Everyone));
        if (mustRefuse)
        {
            Assert.Throws<InvalidOperationException>(() => engine.Modify(section, AclModification.Add, rule));
            // These are deliberate restrictions relative to Microsoft's successful add.
            Assert.NotEqual(inputHex, microsoftOutputHex);
        }
        else
        {
            var result = engine.Modify(section, AclModification.Add, rule);
            Assert.Equal(Convert.FromHexString(microsoftOutputHex), result.Engine.Descriptor.GetBinaryForm());
            Assert.Equal(input, result.Engine.OriginalDescriptor.GetBinaryForm());
            Assert.Equal(section, result.Engine.WriteIntent);
            // The recorded call is void AddAccessRule, so it establishes no bool return.
        }
        Assert.Equal(input, engine.Descriptor.GetBinaryForm());
        Assert.Equal(input, engine.OriginalDescriptor.GetBinaryForm());
        Assert.Equal(SecurityMasks.None, engine.WriteIntent);
    }

    public static IEnumerable<object[]> RecordedI2Mutations()
    {
        yield return new object[] { "I2 DACL common: Allow IO (baseline)", "", "", false, false };
        yield return new object[] { "I2 DACL common: Allow IO|CI (control)", "", "", false, false };
        yield return new object[] { "I2 DACL common: Allow IO|NP", "", "", false, false };
        yield return new object[] { "I2 DACL common: Allow IO|INHERITED", "", "", false, false };
        yield return new object[] { "I2 DACL common: Deny IO", "", "", false, false };
        yield return new object[] { "I2 DACL common: Deny IO|CI (control)", "", "", false, true };
        yield return new object[] { "I2 DACL common: Deny IO|INHERITED", "", "", false, false };
        yield return new object[] { "I2 DACL object: AllowObj IO of=0", "", "", false, false };
        yield return new object[] { "I2 DACL object: AllowObj IO of=1 ot=G1", "", "", false, false };
        yield return new object[] { "I2 DACL object: AllowObj IO of=2 it=G2", "", "", false, false };
        yield return new object[] { "I2 DACL object: AllowObj IO of=3 ot=G1 it=G2", "", "", false, false };
        yield return new object[] { "I2 DACL object: AllowObj IO|CI of=2 it=G2 (control)", "", "", false, false };
        yield return new object[] { "I2 DACL object: DenyObj IO of=1 ot=G1", "", "", false, false };
        yield return new object[] { "I2 DACL object: DenyObj IO of=2 it=G2", "", "", false, false };
        yield return new object[] { "I2 DACL object: DenyObj IO of=3 ot=G1 it=G2", "", "", false, false };
        yield return new object[] { "I2 DACL object: AllowObj IO|INHERITED of=1 ot=G1", "", "", false, false };
        yield return new object[] { "I2 SACL audit: Audit IO|S", "", "", true, true };
        yield return new object[] { "I2 SACL audit: Audit IO|F", "", "", true, true };
        yield return new object[] { "I2 SACL audit: Audit IO|S|F", "", "", true, true };
        yield return new object[] { "I2 SACL audit: Audit IO (no audit flags)", "", "", true, true };
        yield return new object[] { "I2 SACL audit: Audit IO|CI|S (control)", "", "", true, true };
        yield return new object[] { "I2 SACL audit: Audit IO|S|INHERITED", "", "", true, true };
        yield return new object[] { "I2 SACL audit: AuditObj IO|S of=1 ot=G1", "", "", true, true };
        yield return new object[] { "I2 SACL audit: AuditObj IO|S of=2 it=G2", "", "", true, true };
        yield return new object[] { "I2 SACL audit: AuditObj IO|S|F of=3 ot=G1 it=G2", "", "", true, true };
        yield return new object[] { "I2 Excluded (record only): Allow IO with unknown flag 0x20", "", "", false, true };
        yield return new object[] { "I2 Excluded (record only): AllowObj IO unknown object flag 0x4", "", "", false, true };
        yield return new object[] { "I2 Excluded (record only): Allow IO with 4 trailing bytes", "", "", false, true };
        yield return new object[] { "I2 Excluded (record only): AllowCallback IO with app data", "", "", false, true };
        yield return new object[] { "I2 Excluded (record only): AllowCallbackObj IO with app data", "", "", false, true };
        yield return new object[] { "I2 Excluded (record only): Unknown type 0x20 with IO", "", "", false, true };
    }
}
